<script lang="ts">
  import Icon from './Icon.svelte';
  import { faArrowRight, faArrowsRotate, faBoxOpen, faClock, faShareNodes, faShieldHalved, faSliders, faStop, faTowerBroadcast, faUsers, faVolumeHigh } from '@fortawesome/free-solid-svg-icons';
  import { phases, type RoomView } from '../../shared/types';
  import { scenes, phaseLabels, npcs, routes, objectiveLabels, debriefPrompts } from '../../shared/content';
  import { locale } from '../lib/i18n';
  import { command, busy, connection } from '../lib/client';
  import { onDestroy, untrack } from 'svelte';
  import CheckPanel from './CheckPanel.svelte';
  import PollPanel from './PollPanel.svelte';
  import Evidence from './Evidence.svelte';
  import People from './People.svelte';
  import Handover from './Handover.svelte';
  import Debrief from './Debrief.svelte';
  import Seascape from './Seascape.svelte';
  let { game, gm = false, onshare }: { game: RoomView; gm?: boolean; onshare: () => void } = $props();
  let speaking = $state(false), customPlan = $state(''), customCosts = $state(''), customAssumptions = $state('');
  let settingMode = $state(untrack(() => game.settings.mode)), settingDice = $state(untrack(() => game.settings.dice)), settingGms = $state(untrack(() => game.settings.gmCount));
  const t = (zh: string, en: string) => $locale === 'zh-CN' ? zh : en;
  const locked = $derived($busy || $connection !== 'live');
  const scene = $derived(game.phase === 'lobby' ? null : scenes[game.phase]);
  const poll = $derived(game.polls.filter(p => game.phase === 'negotiation' ? p.kind === 'decision' : game.phase === 'route_choice' ? p.kind === 'route' : game.phase === 'execution' ? p.kind === 'kit' && p.checkId === game.checks.at(-1)?.id : false).at(-1));
  const blocked = $derived(game.checks.some(c => c.status !== 'resolved') || game.polls.some(p => p.status === 'open' || (p.tied.length > 0 && !p.outcome)));
  const incomplete = $derived(game.phase === 'investigation' && game.settings.mode === 'full' ? game.checks.filter(c => c.kind === 'preparation' && c.result).length < 3 : game.phase === 'execution' ? game.checks.filter(c => c.kind === 'execution' && c.result).length < 3 : game.phase === 'route_choice' ? !game.route : game.phase === 'lobby' ? !game.members.some(m => m.role === 'player') || game.members.filter(m => m.role === 'gm').length < game.settings.gmCount : game.phase === 'ending' ? !game.report.owner.trim() || !game.report.nextUpdate.trim() || !game.report.statement.trim() : false);
  function read() {
    if (!('speechSynthesis' in window) || !scene) return;
    if (speaking) { speechSynthesis.cancel(); speaking = false; return; }
    const utterance = new SpeechSynthesisUtterance(`${scene.body[$locale]} ${scene.prompt[$locale]}`); utterance.lang = $locale === 'zh-CN' ? 'zh-CN' : 'en-US';
    utterance.onend = utterance.onerror = () => speaking = false;
    speaking = true; speechSynthesis.speak(utterance);
  }
  $effect(() => { game.phase; if ('speechSynthesis' in window) speechSynthesis.cancel(); speaking = false; });
  onDestroy(() => { if ('speechSynthesis' in window) speechSynthesis.cancel(); });
</script>
{#if game.phase === 'lobby'}
  <section class="grid grid-cols-[1fr_.8fr] items-center gap-6 max-lg:grid-cols-1 max-md:gap-0">
    <div><span class="tiny-tag">{t('The Shell · 救援集结', 'The Shell · Rescue assembly')}</span><h1 class="my-[13px] font-serif text-[clamp(29px,3vw,42px)] leading-[1.5] font-medium text-heading max-md:text-[35px]">{t('让我们一起，', 'Together,')}<br />{t('把他们带回来。', 'bring them home.')}</h1><p class="max-w-[360px] text-[12px] leading-[1.85] text-muted max-md:text-[14px]">{t('房间已经准备就绪。邀请同伴加入，选择分工，等主持人宣布任务。', 'Your room is ready. Invite your teammates, choose your roles and wait for the mission briefing.')}</p><button class="btn primary mt-[23px]" onclick={onshare}><Icon icon={faShareNodes} size={17} />{t('邀请同伴', 'Invite the team')}<span class="ml-1.5 border-l border-[#ffffff3b] pl-3 font-normal tracking-[.16em]">{game.code}</span></button></div>
    <div class="min-h-[210px] self-stretch overflow-hidden rounded-[45%_45%_10px_10px] bg-header [&>svg]:h-full [&>svg]:w-full [&>svg]:object-cover max-lg:hidden"><Seascape compact /></div>
  </section>
  <div class="mt-[29px] mb-8 flex flex-wrap gap-x-6 gap-y-3 border-y border-line py-[22px] text-[10px] text-muted [&>span]:flex [&>span]:items-center [&>span]:gap-[7px] max-md:my-[27px] max-md:gap-x-5 max-md:gap-y-3.5 max-md:py-5 max-md:[&>span]:flex-[1_1_40%] max-md:[&_svg]:w-4"><span><Icon icon={faClock} size={17} />{game.settings.mode === 'full' ? t('完整 · 45 + 10 分钟', 'Full · 45 + 10 minutes') : t('精简 · 20 + 5 分钟', 'Short · 20 + 5 minutes')}</span><span><Icon icon={faUsers} size={17} />{game.settings.gmCount} {game.settings.gmCount === 2 ? 'Co-GMs' : 'GMs'}</span><span><Icon icon={faBoxOpen} size={17} />{t('两份共享应急物资', 'Two shared emergency kits')}</span><span>{game.settings.dice === 'physical' ? t('实体 D20 · GM 录入', 'Physical D20 · GM enters') : t('虚拟 D20 · 系统掷骰', 'Virtual D20 · server rolls')}</span></div>
  <People {game} {gm} />
  {#if gm}<details class="gm-details surface"><summary><Icon icon={faSliders} size={16} />{t('房间规则与主持席位', 'Room rules & GM seats')}</summary><form onsubmit={(e) => { e.preventDefault(); command('settings', { mode: settingMode, dice: settingDice, gmCount: settingGms }); }}><div class="form-row"><div><label for="setting-gms">{t('主持人数', 'GM count')}</label><select id="setting-gms" bind:value={settingGms}>{#each [1,2,3,4] as n}<option value={n}>{n}</option>{/each}</select></div><div><label for="setting-mode">{t('剧本', 'Story')}</label><select id="setting-mode" bind:value={settingMode}><option value="full">{t('完整', 'Full')}</option><option value="short">{t('精简', 'Short')}</option></select></div><div><label for="setting-dice">{t('骰子', 'Dice')}</label><select id="setting-dice" bind:value={settingDice}><option value="virtual">{t('虚拟', 'Virtual')}</option><option value="physical">{t('实体', 'Physical')}</option></select></div></div><button class="btn secondary" disabled={locked}>{t('保存设置', 'Save settings')}</button></form><p>{t('本场约定：D20 加一项相关加成（工具 +1 / 工程 +2 / 领导力 +3）；准备与创意最多降 DC 2，取较高者；自然 1 无额外处罚。', 'Session conventions: D20 plus one relevant bonus (tool +1 / engineering +2 / leadership +3). Use the greater preparation or creative reduction, up to 2. Natural 1 has no extra penalty.')}</p></details>{/if}
{:else if scene}
  <section>
    <div class="mb-[18px] flex items-center justify-between gap-[15px] max-md:mb-[13px]"><span class="tiny-tag text-[10px] max-md:text-[9px]">{t('当前章节', 'Current chapter')} {String(phases.indexOf(game.phase)).padStart(2, '0')} / 07</span>{#if 'speechSynthesis' in window}<button class="flex min-h-8 items-center gap-[7px] border-0 bg-transparent text-[10px] text-muted max-md:text-[9px]" onclick={read}>{#if speaking}<Icon icon={faStop} size={14} />{:else}<Icon icon={faVolumeHigh} size={16} />{/if}{speaking ? t('停止朗读', 'Stop reading') : t('朗读背景', 'Read aloud')}</button>{/if}</div>
    <h1 class="max-w-[800px] font-scene text-[clamp(26px,2.5vw,39px)] leading-[1.45] font-medium text-heading min-[1700px]:text-[43px] max-md:text-[29px] max-md:leading-[1.55] max-[360px]:text-[27px]">{scene.title[$locale]}</h1>
    <p class="mt-[21px] max-w-[75ch] text-[15px] leading-[1.95] whitespace-pre-line text-muted max-md:mt-[18px] max-md:text-[16px]">{scene.body[$locale]}</p>
    <div class="mt-[23px] mb-[30px] flex gap-[11px] border-l-2 border-border-hover bg-soft px-4 py-[15px] text-muted max-md:mt-[21px] max-md:mb-[26px] max-md:gap-2 max-md:px-3.5 max-md:py-[13px]"><Icon icon={faTowerBroadcast} size={18} class="mt-[3px] max-md:w-[15px]" /><p class="text-[13px] leading-[1.8] max-md:text-[15px]">{scene.prompt[$locale]}</p></div>
  </section>
  {#if game.phase === 'briefing'}
    <div class="relative max-h-[370px] overflow-hidden rounded-xl [&>svg]:-mt-[7%] [&>svg]:-mb-[8%] max-md:rounded-[9px] max-md:[&>svg]:my-0"><Seascape /><div class="absolute inset-x-0 bottom-0 flex gap-[50px] bg-[linear-gradient(0deg,#133743f0,#13374300)] p-7 text-[#b7cfc0] max-md:gap-[30px] max-md:p-5 [&>span]:text-[10px] max-md:[&>span]:text-[9px] [&_strong]:mt-[7px] [&_strong]:block [&_strong]:text-[22px] [&_strong]:font-normal [&_strong]:text-[#e6efdf] max-md:[&_strong]:text-[18px]"><span>{t('现场时间', 'Story time')}<strong>17:40</strong></span><span>{t('预计暴潮', 'Surge expected')}<strong>17:52</strong></span><span>{t('受困工人', 'Workers inside')}<strong>12</strong></span></div></div>
    <div class="py-[25px]"><h3 class="flex items-center gap-[9px] text-[14px] max-md:items-start max-md:text-[13px] max-md:leading-[1.7]"><Icon icon={faShieldHalved} size={19} />{t('出发前，确认你们已有的保障', 'Before you go, know your safeguards')}</h3><p class="mt-3 text-[12px] text-muted">{t('4 人上层避难室，约两小时保障。诊所独立备用电源 20 分钟。两份全组应急物资。额定 8 人工作艇（含 2 名船员），两趟可运 12 人。', 'Upper refuge: 4 people, roughly two hours. Independent clinic backup: 20 minutes. Two shared emergency kits. An 8-person-rated boat, including 2 crew; two trips can evacuate 12 people.')}</p><small class="mt-[11px] block text-[10px] text-muted">{t('十二分钟是故事时间；课堂讨论不会偷偷消耗行动窗口。', 'The twelve minutes are fictional. Discussion does not secretly consume action windows.')}</small></div>
  {:else if game.phase === 'investigation'}<Evidence {game} inline />{#if game.settings.mode === 'full'}<CheckPanel {game} {gm} />{:else}<div class="inline-info"><Icon icon={faUsers} size={21} /><p>{t('精简版共享全部线索，跳过准备骰。两份物资保留，执行基础 DC 为 12 / 12 / 13，创意仍可最多降低 2。', 'Short mode shares all evidence and skips preparation rolls. Keep both kits. Execution DCs remain 12 / 12 / 13, with creative reductions up to 2.')}</p></div>{/if}
  {:else if game.phase === 'negotiation'}
    <div class="mb-8 grid grid-cols-3 gap-3.5 max-xl:gap-3 max-lg:grid-cols-1">
      {#each npcs as npc, i}
        <article class="flex flex-col rounded-[10px] border border-line bg-surface px-4 py-[19px] max-lg:p-5">
          <div class="flex items-center gap-2"><span class="flex size-[35px] shrink-0 items-center justify-center rounded-full bg-badge font-display text-[19px] text-muted">{npc.name.slice(0, 1)}</span><div class="flex-1"><h3 class="text-[14px] max-md:text-[16px]">{npc.name}</h3><small class="mt-0.5 block text-[8px] leading-[1.5] text-muted max-md:text-[9px]">{npc.guild} · {npc.job[$locale]}</small></div><span class="signal-dot size-1"></span></div>
          <blockquote class="my-5 flex-1 font-serif text-[14px] leading-[1.95] text-muted max-lg:my-4 max-md:text-[15px]">{npc.dialogue[$locale]}</blockquote><p class="border-t border-line pt-3 text-[12px] text-muted max-md:text-[13px]">{npc.boundary[$locale]}</p>
        </article>
      {/each}
    </div>{#if poll}<PollPanel {game} {poll} {gm} />{/if}
  {:else if game.phase === 'route_choice'}
    <div class="grid grid-cols-3 gap-3.5 max-xl:gap-3 max-lg:grid-cols-2 max-md:grid-cols-1">
      {#each routes.filter(r => r.id !== 'custom' || game.customRoute.plan) as route}
        <article class={['relative rounded-[10px] border px-[17px] py-[21px] max-lg:p-[19px] [&>p]:mt-4 [&>p]:text-[14px] [&>p]:leading-[1.85] [&>p]:text-muted max-md:[&>p]:text-[15px]', game.route === route.id ? 'border-border-hover bg-selected' : 'border-line bg-raised']}>
          <span class="mb-4 flex size-[30px] items-center justify-center rounded-[7px] bg-badge font-display text-[14px] text-muted max-md:float-left max-md:mr-3 max-md:mb-2.5 max-md:h-[38px] max-md:w-[33px]">{route.label}</span><h3 class="text-[16px] text-heading">{route.title[$locale]}</h3>{#if $locale === 'zh-CN'}<small class="mt-[3px] block text-[10px] text-muted max-md:pt-0.5">{route.english}</small>{/if}
          <p>{route.id === 'custom' ? game.customRoute.plan : route.method[$locale]}</p>
          <div class="mt-[19px] border-t border-line pt-4 max-md:clear-both"><strong class="text-[10px] font-medium text-muted">{t('公开代价', 'Known costs')}</strong><ul class="mt-2.5 pl-3.5 [&>li]:mt-[7px] [&>li]:text-[12px] [&>li]:leading-[1.8] [&>li]:text-muted max-md:[&>li]:text-[13px]">{#if route.id === 'custom'}<li>{game.customRoute.costs}</li>{:else}{#each route.costs as cost}<li>{cost[$locale]}</li>{/each}{/if}</ul></div>
          {#if route.id === 'custom'}<p class="field-hint">{t('假设：', 'Assumptions: ')}{game.customRoute.assumptions}</p>{/if}
        </article>
      {/each}
    </div>{#if poll}<PollPanel {game} {poll} {gm} />{/if}
    {#if gm}<details class="gm-details surface"><summary>{t('混合 / 自创路线，或重新投票', 'Custom route / restart the vote')}</summary><form onsubmit={(e) => { e.preventDefault(); command('custom_route', { plan: customPlan, costs: customCosts, assumptions: customAssumptions }); }}><label for="custom-plan">{t('三个目标如何完成', 'How will all three objectives be met?')}</label><textarea id="custom-plan" bind:value={customPlan} maxlength="2000" required></textarea><label for="custom-costs">{t('接受的公开代价', 'Accepted public costs')}</label><textarea id="custom-costs" bind:value={customCosts} maxlength="2000" required></textarea><label for="custom-assumptions">{t('需要验证的假设', 'Assumptions to verify')}</label><textarea id="custom-assumptions" bind:value={customAssumptions} maxlength="2000" required></textarea><button class="btn secondary" disabled={locked}>{t('保存自创方案', 'Save custom route')}</button></form><p>{t('保存方案会自动重新开放投票，所有人需确认新的方案与代价。', 'Saving the plan automatically reopens voting. Everyone must approve the new plan and costs.')}</p><button class="btn secondary" disabled={locked} onclick={() => command('route_vote')}><Icon icon={faArrowsRotate} size={15} />{t('重新发起路线投票', 'Restart route vote')}</button></details>{/if}
  {:else if game.phase === 'execution'}{#if game.route}<div class="mb-[25px] flex items-center gap-3.5 rounded-[7px] bg-soft px-[17px] py-3.5 text-[10px] text-muted max-md:flex-wrap max-md:gap-2.5 max-md:px-[13px] max-md:py-3"><span>{t('已选路线', 'Selected route')}</span><strong class="text-[12px] font-[550] text-muted">{routes.find(r => r.id === game.route)?.title[$locale]}</strong><span class="ml-auto max-md:ml-0 max-md:w-full max-md:text-[9px]">{t('三个目标 · 每项一次检定', 'Three objectives · one check each')}</span></div>{/if}<CheckPanel {game} {gm} />{#if poll}<PollPanel {game} {poll} {gm} />{/if}
  {:else if game.phase === 'ending'}<Handover {game} {gm} />
  {:else if game.phase === 'debrief'}<Debrief {game} /><details class="mt-[35px] text-[12px] text-muted"><summary class="min-h-10 cursor-pointer">{t('回看事故交接与救援结果', 'Review the handover and rescue outcomes')}</summary><Handover {game} {gm} /></details>{/if}
{/if}
{#if gm && game.gmContext && game.phase !== 'lobby'}<details class="mt-7 rounded-[7px] border border-dashed border-line px-4 py-3 text-[11px] text-muted max-md:px-3.5 max-md:py-[11px]"><summary class="min-h-[26px] cursor-pointer leading-[26px]">{t('主持人提示 · 仅 GM 可见', 'Facilitator notes · GMs only')}</summary>{#each game.gmContext as hint}<p class="mt-[11px] text-[11px] leading-[1.8] max-md:text-[12px]"><strong class="font-[550]">{hint.name}</strong> {hint.context[$locale]}</p>{/each}</details>{/if}
{#if gm && game.phase !== 'debrief'}<div class="mt-8 flex items-center justify-between gap-6 rounded-[9px] border border-line bg-soft px-[22px] py-[21px] max-lg:gap-[17px] max-lg:p-[18px] max-md:flex-col max-md:items-stretch max-md:gap-[15px]"><div><strong class="text-[12px] font-semibold text-muted max-lg:text-[11px] max-md:text-[12px]">{game.phase === 'lobby' ? t('所有人准备好了吗？', 'Is everyone ready?') : t('留一点空间，听听每个人。', 'Make room for every voice.')}</strong><p class="mt-1.5 text-[12px] text-muted max-md:text-[13px]">{blocked ? t('先完成当前投票或检定。', 'Finish the current vote or check.') : incomplete ? game.phase === 'lobby' ? t('请补齐主持席位，并至少加入一名玩家。', 'Fill the GM seats and add at least one player.') : game.phase === 'ending' ? t('请保存通报原话、负责人和更新时间。', 'Save the statement, owner and update time.') : t('完成当前阶段的目标后继续。', 'Complete this stage’s objectives to continue.') : t('继续会为所有人更新背景与下一步任务。', 'Continue to share the next scene and task with everyone.')}</p></div><button class="btn primary shrink-0 max-lg:px-[13px] max-lg:py-[11px] max-md:min-h-[46px]" disabled={locked || blocked || incomplete} onclick={() => command('next')}>{game.phase === 'lobby' ? t('开始任务', 'Begin the mission') : phaseLabels[phases[phases.indexOf(game.phase) + 1]][$locale]}<Icon icon={faArrowRight} size={18} /></button></div>{/if}
